:host {
    position: relative;
    border-radius: var(--tumaet-ui-radius-md);
    text-decoration: none;
}

:host {
    &::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: inherit;
        background-color: transparent;
        pointer-events: none;
        transition: background-color 0.15s ease;
    }

    // aria-disabled buttons stay hoverable so they can show their tooltip; they must not look interactive.
    &:hover:not(:disabled):not([aria-disabled='true'])::after {
        background-color: color-mix(in srgb, var(--tumaet-ui-text-color) 5%, transparent);
    }

    &:focus-visible {
        outline: 2px solid var(--tumaet-ui-focus-color);
        outline-offset: 2px;
    }

    &:disabled {
        cursor: default;
    }

    // Stated here rather than left to a utility class: an application's unlayered rules can set cursor:pointer on
    // enabled buttons, and unlayered always beats a cascade layer, whatever the specificity of the utility.
    &[aria-disabled='true'] {
        cursor: not-allowed;
    }
}

