             * the two flicker against each other. Only the offset direction depends on which side it is on.
             */
            pointer-events: none;
        }
        :host([data-below='true']) {
            transform: translate(-50%, 12px);
        }
        .tum-ui-chart-tooltip-title {
            font-weight: 600;
        }
