:host {
    position: relative;
    display: inline-flex;

    // The fallback is what keeps the control square. Without it, a context that does not carry the spacing token makes
    // both calc() values invalid: the width collapses to nothing, and the height falls back to auto, at which point a
    // flex row's default `stretch` grows the control to the height of its label. Beside a label that wraps onto several
    // lines that is a tall thin rectangle rather than a checkbox.
    width: calc(var(--tumaet-ui-spacing, 0.25rem) * 5);
    height: calc(var(--tumaet-ui-spacing, 0.25rem) * 5);

    // Neither grow nor shrink: the height is fixed, so a width that gave way in a tight row - a long label, a narrow
    // column, or the page zoomed in - would deform the box just as surely. tum-ui-toggle-switch is fixed-size for the
    // same reason.
    flex: 0 0 auto;
    vertical-align: bottom;
    user-select: none;
}

.tum-ui-checkbox-input {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    z-index: 1;
    opacity: 0;
    cursor: pointer;
    appearance: none;

    &:disabled {
        cursor: default;
    }
}

.tum-ui-checkbox-box {
    // width/height are 100% of the host and a border is added on top, so this must measure the border inside
    // those 100%. The kit ships no global reset, and relying on the host application's would leave the box
    // two pixels taller than it is wide wherever there is none.
    box-sizing: border-box;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    border-width: 1px;
    border-style: solid;
    border-radius: var(--tumaet-ui-radius-sm);
    box-shadow:
        0 0 transparent,
        0 0 transparent,
        0 1px 2px 0 color-mix(in srgb, var(--tumaet-ui-text-color) 5%, transparent);
    transition:
        background 0.2s,
        border-color 0.2s,
        box-shadow 0.2s,
        outline-color 0.2s;

    &::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: inherit;
        background-color: transparent;
        pointer-events: none;
        transition: background-color 0.15s ease;
    }
}

.tum-ui-checkbox-icon {
    font-size: var(--tumaet-ui-font-size-sm);
    line-height: 1;
}

:host:has(.tum-ui-checkbox-input:hover:not(:disabled)) .tum-ui-checkbox-box::after {
    background-color: color-mix(in srgb, var(--tumaet-ui-text-color) 5%, transparent);
}

:host:has(.tum-ui-checkbox-input:focus-visible) .tum-ui-checkbox-box {
    outline: 2px solid var(--tumaet-ui-focus-color);
    outline-offset: 2px;
}

@media (forced-colors: active) {
    .tum-ui-checkbox-input {
        appearance: auto;
        opacity: 1;
    }

    .tum-ui-checkbox-box {
        display: none;
    }
}

