 * ```
 *
 * Use `tum-ui-table` instead when the content is tabular and needs sorting, selection, or column headers.
 */
@Component({
    selector: 'tum-ui-list',
    templateUrl: './tum-ui-list.component.html',
    styleUrl: './tum-ui-list.component.scss',
    host: {
        class: 'tum-ui-list',
