@if (showSearch()) {
    <div class="tum:mb-3">
        <div class="tum:relative">
            <fa-icon [icon]="faMagnifyingGlass" class="tum:pointer-events-none tum:absolute tum:start-3 tum:top-1/2 tum:-translate-y-1/2 tum:text-muted" />
            <input
                #searchInput
                type="search"
                [placeholder]="searchPlaceholder() | tumUiTranslate"
                [attr.aria-label]="searchPlaceholder() | tumUiTranslate"
                (input)="onSearchInput(searchInput.value)"
                class="tum:box-border tum:w-full tum:rounded-md tum:border tum:border-control-border tum:bg-control-background tum:py-1.5 tum:ps-10 tum:pe-3 tum:text-sm tum:text-text"
            />
        </div>
    </div>
}

<div
    class="tum:relative tum:w-full tum:max-w-full tum:overflow-x-auto"
    [style.overflow-y]="scrollable() ? 'auto' : null"
    [style.flex]="scrollHeight() === 'flex' ? '1 1 0%' : null"
    [style.min-height]="scrollHeight() === 'flex' ? 0 : null"
    [style.max-height]="scrollHeight() && scrollHeight() !== 'flex' ? scrollHeight() : null"
>
    <table cdk-table [dataSource]="rows()" [trackBy]="effectiveTrackBy()" [class]="tableClasses()" [attr.aria-busy]="loading() ? 'true' : null">
        @for (col of columns(); track columnName(col, $index)) {
            <ng-container [cdkColumnDef]="columnName(col, $index)">
                <th
                    cdk-header-cell
                    *cdkHeaderCellDef
                    scope="col"
                    [style.min-width]="col.width"
                    [attr.aria-sort]="ariaSortFor(col)"
                    [class]="headerCellClasses(col)"
                    class="tum:border-border tum:bg-content-background tum:px-4 tum:py-2 tum:text-start tum:font-semibold tum:text-text"
                >
                    <span class="tum:inline-flex tum:items-center tum:gap-1">
                        @if (col.sort && col.field) {
                            <button
                                type="button"
                                class="tum:inline-flex tum:cursor-pointer tum:appearance-none tum:items-center tum:gap-2 tum:border-0 tum:bg-transparent tum:p-0 tum:font-semibold tum:text-text tum:hover:text-accent"
                                (click)="onSortClick(col)"
                            >
                                @if (col.headerKey) {
                                    <span>{{ col.headerKey | tumUiTranslate }}</span>
                                } @else {
                                    <span>{{ col.header }}</span>
                                }
                                <fa-icon [icon]="sortIcon(col)" class="tum:shrink-0 tum:text-muted" />
                            </button>
                        } @else if (col.headerKey) {
                            <span>{{ col.headerKey | tumUiTranslate }}</span>
                        } @else {
                            <span>{{ col.header }}</span>
                        }
                        @if (col.headerTooltip; as headerTooltip) {
                            @let tooltipText = headerTooltip | tumUiTranslate;
                            <button
                                type="button"
                                class="tum:inline-flex tum:cursor-help tum:appearance-none tum:items-center tum:border-0 tum:bg-transparent tum:p-0 tum:text-muted"
                                [tumUiTooltip]="tooltipText"
                                [attr.aria-label]="tooltipText"
                            >
                                <fa-icon [icon]="faCircleQuestion" />
                            </button>
                        }
                    </span>
                </th>
                <td cdk-cell *cdkCellDef="let row; let i = index" [class]="columnVisibilityClasses(col)" class="tum:border-border tum:px-4 tum:py-2 tum:text-text">
                    @if (col.templateRef) {
                        <ng-container [ngTemplateOutlet]="col.templateRef" [ngTemplateOutletContext]="{ $implicit: cellParams(row, col, i) }" />
                    } @else {
                        {{ resolveValue(row, col) }}
                    }
                </td>
            </ng-container>
        }

        @if (rowActions(); as actions) {
            <ng-container [cdkColumnDef]="ACTIONS_COLUMN">
                <th cdk-header-cell *cdkHeaderCellDef scope="col" class="tum:border-border tum:bg-content-background tum:px-4 tum:py-2">
                    <span class="tum:sr-only">{{ 'tumUi.table.actions' | tumUiTranslate }}</span>
                </th>
                <!-- Declares no width, so it is the one column auto layout can squeeze: nowrap keeps the controls on one line. -->
                <td cdk-cell *cdkCellDef="let row" class="tum:border-border tum:px-4 tum:py-2 tum:text-end tum:whitespace-nowrap">
                    <ng-container [ngTemplateOutlet]="actions" [ngTemplateOutletContext]="{ $implicit: row }" />
                </td>
            </ng-container>
        }

        <tr cdk-header-row *cdkHeaderRowDef="displayedColumns(); sticky: scrollable()" class="tum:bg-content-background"></tr>
        <tr cdk-row *cdkRowDef="let row; columns: displayedColumns()" [class.tum-ui-table-row-highlighted]="rowHighlighted()?.(row) ?? false"></tr>

        <tr *cdkNoDataRow>
            <td [attr.colspan]="displayedColumns().length" class="tum:bg-content-background tum:px-4 tum:py-6 tum:text-center tum:text-muted">
                <span>{{ emptyMessage() | tumUiTranslate }}</span>
            </td>
        </tr>
    </table>

    @if (loading()) {
        <div class="tum:absolute tum:inset-0 tum:flex tum:items-center tum:justify-center tum:bg-content-background/60" aria-hidden="true">
            <span class="tum:h-6 tum:w-6 tum:animate-spin tum:rounded-full tum:border-2 tum:border-border tum:border-t-primary tum:motion-reduce:animate-none"></span>
        </div>
    }
</div>

<tum-ui-paginator
    [totalRecords]="totalRecords()"
    [page]="currentPage()"
    [pageSize]="effectivePageSize()"
    [pageSizeOptions]="pageSizeOptions()"
    [showRowsPerPage]="showRowsPerPage()"
    [showCurrentPageReport]="showCurrentPageReport()"
    [disabled]="loading()"
    (pageChange)="onPageChange($event)"
    (pageSizeChange)="onPageSizeChange($event)"
/>

